// SPDX-License-Identifier: MIT
pragma solidity =0.8.24;

library SupraOracleDecoder {
    struct CommitteeFeed {
        uint32 pair;
        uint128 price;
        uint64 timestamp;
        uint16 decimals;
        uint64 round;
    }

    struct CommitteeFeedWithProof {
        CommitteeFeed[] committee_feeds;
        bytes32[] proofs;
        bool[] flags;
    }

    struct PriceDetailsWithCommittee {
        uint64 committee_id;
        bytes32 root;
        uint256[2] sigs;
        CommitteeFeedWithProof committee_data;
    }

    struct OracleProofV2 {
        PriceDetailsWithCommittee[] data;
    }

    function decodeOracleProof(
        bytes calldata _bytesProof
    ) external pure returns (OracleProofV2 memory) {
        return abi.decode(_bytesProof, (OracleProofV2));
    }
}

contracts/0xVault/LpProvider.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity =0.8.24;

// Import necessary OpenZeppelin contracts and interfaces
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import {IVault} from "./interfaces/IVault.sol";
import {Crypto} from "./libs/Crypto.sol";
import {IOracle} from "./interfaces/IOracle.sol";

/**
 * @title LpProvider
 * @dev A contract for managing liquidity provision and fund management
 * This contract allows LP providers to deposit funds, request withdrawals,
 * and manage liquidity for different tokens.
 */
contract LpProvider is OwnableUpgradeable, ReentrancyGuardUpgradeable {
    // Constants
    uint256 public constant NAV_DECIMALS = 18; // Used for precision in calculations

    // State variables
    address public vault; // Address of the associated vault contract
    address public coldWallet; // Address of the cold wallet for fund storage
    address public oracle; // Address of the price oracle contract
    uint256 public startEpochTimestamp; // Timestamp of the start of the epoch
    uint256 public epochPeriod; // Duration of each epoch
    uint256 public withdrawalDelayTime; // Delay time for withdrawals
    mapping(address => uint256) public pairId; // token => pairId
    mapping(address => bool) public isTokenSupported;

    // Mappings
    mapping(address => bool) public isLPProvider; // Tracks whether an address is an LP provider
    mapping(address => uint256) public lpProvidedAmount; // Amount of liquidity provided by each LP provider
    mapping(address => uint256) public fundAmount; // Total token amount for each token
    mapping(address => uint256) public totalNAVs; // Total NAVs for each token (10^18 decimals)
    mapping(address => mapping(address => uint256)) public userNAVs; // NAVs for each user and token (10^18 decimals)
    mapping(address => mapping(address => ReqWithdraw)) public reqWithdraws; // Withdrawal requests for each user and token

    uint256 public navPrice; // Used for precision in calculations

    // Structs
    struct ReqWithdraw {
        uint256 navAmount; // Amount of NAVs requested for withdrawal
        uint256 timestamp; // Timestamp when the withdrawal can be executed
    }

    // Events
    event LPProvided(
        address indexed user,
        address indexed token,
        uint256 amount
    );
    event LPWithdrawn(
        address indexed user,
        address indexed token,
        uint256 amount
    );
    event DepositFund(
        address indexed user,
        address indexed token,
        uint256 amount,
        uint256 fundAmount
    );
    event WithdrawFund(
        address indexed user,
        address indexed token,
        uint256 amount,
        uint256 fundAmount
    );
    event WithdrawRequested(
        address indexed user,
        address indexed token,
        uint256 navAmount,
        uint256 timestamp
    );
    event LPProviderStatusChanged(address indexed lpProvider, bool isProvider);
    event VaultChanged(address indexed newVault);
    event ColdWalletChanged(address indexed newColdWallet);
    event OracleChanged(address indexed newOracle);
    event EpochParametersChanged(
        uint256 newStartEpochTimestamp,
        uint256 newEpochPeriod
    );
    event WithdrawalDelayTimeChanged(uint256 newWithdrawalDelayTime);
    event RewardDepositedForMarketMaker(address indexed token, uint256 amount);
    event NAVPriceUpdated(uint256 newPrice);

    event TokenAdded(address indexed token);
    event TokenRemoved(address indexed token);

    // Modifiers
    modifier onlyVault() {
        require(msg.sender == vault, "Only vault");
        _;
    }

    // Initialization function
    function initialize(
        address _owner,
        address _vault,
        address _oracle,
        uint256 _epochPeriod,
        uint256 _startEpochTimestamp,
        uint256 _withdrawalDelayTime,
        address _coldWallet
    ) public initializer {
        __Ownable_init(_owner);
        __ReentrancyGuard_init();
        vault = _vault;
        oracle = _oracle;
        epochPeriod = _epochPeriod;
        startEpochTimestamp = _startEpochTimestamp;
        withdrawalDelayTime = _withdrawalDelayTime;
        coldWallet = _coldWallet;

        // Emit events for initial parameter settings
        emit VaultChanged(_vault);
        emit OracleChanged(_oracle);
        emit EpochParametersChanged(_startEpochTimestamp, _epochPeriod);
        emit WithdrawalDelayTimeChanged(_withdrawalDelayTime);
        emit ColdWalletChanged(_coldWallet);
    }

    // Private functions

    /**
     * @dev Calculates the NAV amount based on the token amount
     * @param token The address of the token
     * @param amount The amount of tokens
     * @return The calculated NAV amount
     */
    function _calcNAVAmount(
        address token,
        uint256 amount
    ) private view returns (uint256) {
        IOracle.priceFeed memory oraclePrice = IOracle(oracle).getSvalue(pairId[token]);
        uint256 usdAmount = amount * oraclePrice.price;
        if (NAV_DECIMALS >= oraclePrice.decimals) {
            return
                (usdAmount * (10 ** (NAV_DECIMALS - oraclePrice.decimals))) /
                navPrice;
        } else {
            return
                (usdAmount / (10 ** (oraclePrice.decimals - NAV_DECIMALS))) /
                navPrice;
        }
    }

    /**
     * @dev Calculates the token amount based on the NAV amount
     * @param token The address of the token
     * @param navAmount The navAmount of tokens
     * @return The calculated amount
     */
    function _calcAmountFromNAV(
        address token,
        uint256 navAmount
    ) private view returns (uint256) {
        IOracle.priceFeed memory oraclePrice = IOracle(oracle).getSvalue(pairId[token]);
        if (NAV_DECIMALS >= oraclePrice.decimals) {
            return
                ((navAmount * navPrice) /
                    (10 ** (NAV_DECIMALS - oraclePrice.decimals))) /
                oraclePrice.price;
        } else {
            return
                ((navAmount * navPrice) *
                    (10 ** (oraclePrice.decimals - NAV_DECIMALS))) /
                oraclePrice.price;
        }
    }

    /**
     * @dev Deposits funds into the contract
     * @param token The address of the token to deposit
     * @param amount The amount of tokens to deposit
     */
    function _depositFund(address token, uint256 amount) private {
        require(amount > 0, "Amount must be greater than zero");
        require(isTokenSupported[token], "Token not supported");

        require(
            IERC20(token).transferFrom(msg.sender, coldWallet, amount),
            "Transfer failed"
        );
        if (navPrice == 0) {
            navPrice = 1 * (10 ** NAV_DECIMALS); // Set initial NAV price to 1 for first time
        }

        uint256 navs = _calcNAVAmount(token, amount);
        userNAVs[token][msg.sender] += navs;
        fundAmount[token] += amount;
        totalNAVs[token] += navs;
        emit DepositFund(msg.sender, token, amount, fundAmount[token]);
    }

    /**
     * @dev Withdraws funds from the contract
     * @param token The address of the token to withdraw
     * @param navsAmount The amount of NAVs to withdraw
     */
    function _withdrawFund(address token, uint256 navsAmount) private {
        require(navsAmount > 0, "Amount must be greater than zero");
        require(userNAVs[token][msg.sender] >= navsAmount, "Insufficient fund");

        uint256 tokenAmount = _calcAmountFromNAV(token, navsAmount);
        userNAVs[token][msg.sender] -= navsAmount;
        totalNAVs[token] -= navsAmount;
        fundAmount[token] -= tokenAmount;

        require(
            IERC20(token).transfer(msg.sender, tokenAmount),
            "Transfer failed"
        );

        emit WithdrawFund(msg.sender, token, tokenAmount, fundAmount[token]);
    }

    // External functions

    /**
     * @dev Allows LP providers to deposit funds
     * @param token The address of the token to deposit
     * @param amount The amount of tokens to deposit
     */
    function depositFund(address token, uint256 amount) external nonReentrant {
        require(isLPProvider[msg.sender], "Not LP provider");
        _depositFund(token, amount);
    }

    /**
     * @dev Allows LP providers to request a withdrawal
     * @param token The address of the token to withdraw
     * @param navsAmount The amount of NAVs to withdraw
     */
    function requestWithdrawFund(
        address token,
        uint256 navsAmount
    ) external nonReentrant {
        require(isLPProvider[msg.sender], "Not LP provider");
        require(userNAVs[token][msg.sender] >= navsAmount, "Insufficient fund");
        uint256 withdrawTimestamp = block.timestamp + withdrawalDelayTime;
        reqWithdraws[token][msg.sender] = ReqWithdraw(
            navsAmount,
            withdrawTimestamp
        );
        emit WithdrawRequested(
            msg.sender,
            token,
            navsAmount,
            withdrawTimestamp
        );
    }

    /**
     * @dev Allows LP providers to withdraw funds after the delay period
     * @param token The address of the token to withdraw
     */
    function withdrawFund(address token) external nonReentrant {
        require(isLPProvider[msg.sender], "Not LP provider");
        ReqWithdraw memory reqWithdraw = reqWithdraws[token][msg.sender];
        require(
            block.timestamp >= reqWithdraw.timestamp,
            "Withdrawal delay not met"
        );
        _withdrawFund(token, reqWithdraw.navAmount);
        delete reqWithdraws[token][msg.sender];
    }

    /**
     * @dev Allows LP providers to provide liquidity
     * @param token The address of the token to provide liquidity for
     * @param amount The amount of tokens to provide as liquidity
     */
    function provideLiquidity(
        address token,
        uint256 amount
    ) external nonReentrant {
        require(isLPProvider[msg.sender], "Not LP provider");
        require(amount > 0, "Amount must be greater than zero");
        require(isTokenSupported[token], "Token not supported");

        require(
            IERC20(token).transferFrom(msg.sender, address(this), amount),
            "Transfer failed"
        );

        lpProvidedAmount[token] += amount;
        emit LPProvided(msg.sender, token, lpProvidedAmount[token]);
    }

    /**
     * @dev Allows LP providers to withdraw all their provided liquidity
     * @param token The address of the token to withdraw liquidity from
     */
    function withdrawAllLiquidity(address token) external nonReentrant {
        require(isLPProvider[msg.sender], "Not LP provider");
        require(isTokenSupported[token], "Token not supported");
        uint256 amount = lpProvidedAmount[token];
        require(amount > 0, "No liquidity to withdraw");
        require(IERC20(token).transfer(msg.sender, amount), "Transfer failed");

        lpProvidedAmount[token] = 0;

        emit LPWithdrawn(msg.sender, token, amount);
    }

    // Vault-only functions

    /**
     * @dev Increases the LP provided amount (can only be called by the vault)
     * @param token The address of the token
     * @param amount The amount to increase
     */
    function increaseLpProvidedAmount(
        address token,
        uint256 amount
    ) external onlyVault {
        lpProvidedAmount[token] += amount;
        emit LPProvided(address(this), token, amount);
    }

    /**
     * @dev Decreases the LP provided amount (can only be called by the vault)
     * @param token The address of the token
     * @param amount The amount to decrease
     */
    function decreaseLpProvidedAmount(
        address token,
        uint256 amount
    ) external onlyVault {
        require(lpProvidedAmount[token] >= amount, "Insufficient LP amount");
        require(IERC20(token).transfer(vault, amount), "Transfer failed");
        lpProvidedAmount[token] -= amount;
        emit LPWithdrawn(address(this), token, amount);
    }

    // Owner-only functions

    /**
     * 
     * @param token address of the token
     * @param isSupported boolean value indicating whether the token is supported
     */
    function setSupportedToken(
        address token,
        bool isSupported
    ) external onlyOwner {
        isTokenSupported[token] = isSupported;
        if (isSupported) {
            emit TokenAdded(token);
        } else {
            emit TokenRemoved(token);
        }
    }

    /**
     * @dev Sets the LP provider status for multiple addresses
     * @param lpProvider Array of LP provider addresses
     * @param isProvider Array of boolean values indicating LP provider status
     */
    function setLPProvider(
        address[] calldata lpProvider,
        bool[] calldata isProvider
    ) external onlyOwner {
        require(lpProvider.length == isProvider.length, "Invalid input");
        for (uint256 i = 0; i < lpProvider.length; i++) {
            isLPProvider[lpProvider[i]] = isProvider[i];
            emit LPProviderStatusChanged(lpProvider[i], isProvider[i]);
        }
    }

    /**
     * @dev Updates the NAV price for a token
     * @param newPrice The new NAV price
     */
    function setNAVPrice(uint256 newPrice) external onlyOwner {
        require(newPrice > 0, "Invalid NAV price");
        navPrice = newPrice;
        emit NAVPriceUpdated(newPrice);
    }

    /**
     * @dev Sets the vault address
     * @param _vault The new vault address
     */
    function setVault(address _vault) external onlyOwner {
        require(_vault != address(0), "Invalid vault address");
        vault = _vault;
        emit VaultChanged(_vault);
    }

    /**
     * @dev Sets the cold wallet address
     * @param _coldWallet The new cold wallet address
     */
    function setColdWallet(address _coldWallet) external onlyOwner {
        require(_coldWallet != address(0), "Invalid cold wallet address");
        coldWallet = _coldWallet;
        emit ColdWalletChanged(_coldWallet);
    }

    /**
     * @dev Sets the oracle address
     * @param _oracle The new oracle address
     */
    function setOracle(address _oracle) external onlyOwner {
        require(_oracle != address(0), "Invalid oracle address");
        oracle = _oracle;
        emit OracleChanged(_oracle);
    }

    function setPairIDForTokens(
        address[] calldata tokens,
        uint256[] calldata ids
    ) external onlyOwner {
        require(tokens.length == ids.length, "Invalid input");
        for (uint256 i = 0; i < tokens.length; i++) {
            pairId[tokens[i]] = ids[i];
        }
    }

    /**
     * @dev Sets the epoch parameters
     * @param _startEpochTimestamp The new start epoch timestamp
     * @param _epochPeriod The new epoch period
     */
    function setEpochParameters(
        uint256 _startEpochTimestamp,
        uint256 _epochPeriod
    ) external onlyOwner {
        startEpochTimestamp = _startEpochTimestamp;
        epochPeriod = _epochPeriod;
        emit EpochParametersChanged(_startEpochTimestamp, _epochPeriod);
    }

    /**
     * @dev Sets the withdrawal delay time
     * @param _withdrawalDelayTime The new withdrawal delay time
     */
    function setWithdrawalDelayTime(
        uint256 _withdrawalDelayTime
    ) external onlyOwner {
        withdrawalDelayTime = _withdrawalDelayTime;
        emit WithdrawalDelayTimeChanged(_withdrawalDelayTime);
    }

    /**
     * @dev Deposits rewards for market makers
     * @param token The address of the token to deposit
     * @param amount The amount of tokens to deposit
     */
    function depositRewardForMarketMaker(
        address token,
        uint256 amount
    ) external onlyOwner {
        require(amount > 0, "Amount must be greater than zero");
        require(isTokenSupported[token], "Token not supported");

        require(
            IERC20(token).transferFrom(msg.sender, address(this), amount),
            "Transfer failed"
        );
        fundAmount[token] += amount;
        emit RewardDepositedForMarketMaker(token, amount);
    }
}

contracts/0xVault/Vault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity =0.8.24;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import {IOracle} from "./interfaces/IOracle.sol";
import {ISupraVerifier} from "./interfaces/ISupraVerifier.sol";
import {ILpProvider} from "./interfaces/ILpProvider.sol";
import {Crypto} from "./libs/Crypto.sol";
import {Dex} from "./libs/Dex.sol";
import {SupraOracleDecoder} from "./libs/SupraOracleDecoder.sol";

/**
 * @custom:oz-upgrades-from Vault
 */
contract Vault is
    OwnableUpgradeable,
    ReentrancyGuardUpgradeable,
    PausableUpgradeable
{
    uint256 public signatureExpiryTime;
    uint256 private constant SECP256K1_CURVE_N =
        0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141;

    uint32 private _requestIdCounter;

    mapping(uint32 => Dispute) public _disputes;
    // mapping(uint32 => ClosePositionDispute) private _positionDisputes;
    mapping(bytes => bool) private _signatureUsed;
    mapping(bytes => bool) private _schnorrSignatureUsed;
    mapping(uint32 => uint32) private _latestSchnorrSignatureId;

    mapping(address => address) public combinedPublicKey;
    uint256 constant ONE = 1e9;
    // for adding LP
    mapping(address => mapping(address => uint256)) public depositedAmount; // address => token => amount
    address public lpProvider;
    address public dexSupporter;
    // uint256 public lastPausedTime;

    struct TokenBalance {
        address token;
        uint256 balance;
    }

    event Deposited(
        address indexed user,
        address indexed token,
        uint256 amount
    );
    event Withdrawn(
        address indexed user,
        address indexed token,
        uint256 amount
    );
    event WithdrawalRequested(
        address indexed user,
        address indexed token,
        uint256 amount,
        uint32 requestId
    );
    event LPProvided(
        address indexed user,
        address indexed token,
        uint256 amount
    );
    event LPWithdrawn(
        address indexed user,
        address indexed token,
        uint256 amount
    );
    event PartialLiquidation(
        address indexed user,
        address indexed token,
        uint256 amount
    );

    error InvalidSignature();
    error InvalidUsedSignature();
    error InvalidSchnorrSignature();
    error InvalidSP();
    error ECRecoverFailed();
    error InvalidAddress();
    error DisputeChallengeFailed();
    error SettleDisputeFailed();
    error DataNotVerified();

    struct WithdrawParams {
        address trader;
        address token;
        uint256 amount;
        uint64 timestamp;
    }

    // for liquidation case
    struct OraclePrice {
        string positionId;
        address token;
        uint256 price;
        uint64 timestamp;
    }

    enum DisputeStatus {
        None,
        Opened,
        Challenged,
        Settled
    }

    struct Dispute {
        address user;
        address challenger;
        uint64 timestamp;
        Crypto.Balance[] balances;
        Crypto.Position[] positions;
        uint8 status;
        uint32 sessionId;
    }

    struct ClosePositionDispute {
        address user;
        address challenger;
        uint64 timestamp;
        Crypto.Position[] positions;
        uint8 status;
        uint32 sessionId;
    }

    event DisputeOpened(uint32 requestId, address indexed user);
    event DisputeChallenged(uint32 requestId, address indexed user);
    event PositionDisputeChallenged(uint32 requestId, address indexed user);
    event DisputeSettled(uint32 requestId, address indexed user);

    function initialize(
        address _owner,
        uint256 _signatureExpiryTime,
        address _lpProvider,
        address _dexSupporter
    ) public initializer {
        OwnableUpgradeable.__Ownable_init(_owner);
        __Pausable_init();
        signatureExpiryTime = _signatureExpiryTime;
        lpProvider = _lpProvider;
        dexSupporter = _dexSupporter;
    }

    function deposit(
        address token,
        uint256 amount
    ) external nonReentrant whenNotPaused {
        require(amount > 0, "Amount must be greater than zero");
        require(ILpProvider(lpProvider).isTokenSupported(token), "Token not supported");

        require(
            IERC20(token).transferFrom(msg.sender, address(this), amount),
            "Transfer failed"
        );

        depositedAmount[msg.sender][token] += amount;
        emit Deposited(msg.sender, token, amount);
    }

    function withdrawSchnorr(
        address _combinedPublicKey,
        Crypto.SchnorrSignature calldata _schnorr
    ) external nonReentrant whenNotPaused {
        Crypto.SchnorrDataWithdraw memory schnorrData = Crypto
            .decodeSchnorrDataWithdraw(_schnorr, combinedPublicKey[msg.sender]);

        require(schnorrData.amount > 0, "Amount must byese greater than zero");
        require(ILpProvider(lpProvider).isTokenSupported(schnorrData.token), "Token not supported");

        require(
            block.timestamp - schnorrData.timestamp < signatureExpiryTime,
            "Signature Expired"
        );

        if (schnorrData.trader != msg.sender) {
            revert InvalidSchnorrSignature();
        }

        combinedPublicKey[msg.sender] = _combinedPublicKey;

        require(
            IERC20(schnorrData.token).transfer(msg.sender, schnorrData.amount),
            "Transfer failed"
        );

        emit Withdrawn(msg.sender, schnorrData.token, schnorrData.amount);
    }

    function withdrawAndClosePositionTrustlessly(
        Crypto.SchnorrSignature calldata _schnorr
    ) external nonReentrant whenNotPaused {
        Crypto.SchnorrData memory schnorrData = Crypto.decodeSchnorrData(
            _schnorr
        );

        if (schnorrData.addr != msg.sender) {
            revert InvalidSchnorrSignature();
        }

        if (
            !Crypto._verifySchnorrSignature(
                _schnorr,
                combinedPublicKey[schnorrData.addr]
            )
        ) {
            revert InvalidSchnorrSignature();
        }

        if (_schnorrSignatureUsed[_schnorr.signature]) {
            revert InvalidSchnorrSignature();
        }

        _requestIdCounter = _requestIdCounter + 1;
        uint32 requestId = _requestIdCounter;
        _disputes[requestId].timestamp = uint64(block.timestamp);
        uint256 len = schnorrData.balances.length;
        uint256 posLen = schnorrData.positions.length;
        for (uint256 i = 0; i < posLen; i++) {
            Crypto.Position storage newPosition = _disputes[requestId]
                .positions
                .push();

            newPosition.positionId = schnorrData.positions[i].positionId;
            newPosition.token = schnorrData.positions[i].token;
            newPosition.quantity = schnorrData.positions[i].quantity;
            newPosition.isLong = schnorrData.positions[i].isLong;
            newPosition.entryPrice = schnorrData.positions[i].entryPrice;
            newPosition.createdTimestamp = schnorrData
                .positions[i]
                .createdTimestamp;

            uint256 colLen = schnorrData.positions[i].collaterals.length;
            for (uint256 j = 0; j < colLen; j++) {
                newPosition.collaterals.push(
                    Crypto.Collateral({
                        token: schnorrData.positions[i].collaterals[j].token,
                        oracleId: schnorrData
                            .positions[i]
                            .collaterals[j]
                            .oracleId,
                        quantity: schnorrData
                            .positions[i]
                            .collaterals[j]
                            .quantity,
                        entryPrice: schnorrData
                            .positions[i]
                            .collaterals[j]
                            .entryPrice
                    })
                );
            }
        }
        for (uint256 i = 0; i < len; i++) {
            _disputes[requestId].balances.push(schnorrData.balances[i]);
        }

        uint32 signatureId = schnorrData.signatureId;
        _latestSchnorrSignatureId[requestId] = signatureId;
        _schnorrSignatureUsed[_schnorr.signature] = true;

        _openDispute(requestId, msg.sender);
    }

    function _openDispute(uint32 requestId, address user) private {
        Dispute storage dispute = _disputes[requestId];
        dispute.status = uint8(DisputeStatus.Opened);
        dispute.user = user;

        emit DisputeOpened(requestId, user);
    }

    function challengeDispute(
        uint32 requestId,
        Crypto.SchnorrSignature calldata _schnorr
    ) external nonReentrant whenNotPaused {
        Dispute storage dispute = _disputes[requestId];
        Crypto.SchnorrData memory schnorrData = Crypto.decodeSchnorrData(
            _schnorr
        );
        require(
            dispute.status == uint8(DisputeStatus.Opened),
            "Invalid dispute status"
        );
        require(
            block.timestamp < dispute.timestamp + 1800, // fake 30m
            "Dispute window closed"
        );

        if (
            !Crypto._verifySchnorrSignature(
                _schnorr,
                combinedPublicKey[schnorrData.addr]
            )
        ) {
            revert InvalidSchnorrSignature();
        }

        uint32 signatureId = schnorrData.signatureId;

        if (_latestSchnorrSignatureId[requestId] < schnorrData.signatureId) {
            _latestSchnorrSignatureId[requestId] = signatureId;

            dispute.challenger = msg.sender;
            delete dispute.balances;
            delete dispute.positions;
            uint256 len = schnorrData.balances.length;
            uint256 posLen = schnorrData.positions.length;
            for (uint256 i = 0; i < len; i++) {
                dispute.balances.push(schnorrData.balances[i]);
            }
            for (uint256 i = 0; i < posLen; i++) {
                Crypto.Position storage newPosition = _disputes[requestId]
                    .positions
                    .push();

                newPosition.positionId = schnorrData.positions[i].positionId;
                newPosition.token = schnorrData.positions[i].token;
                newPosition.quantity = schnorrData.positions[i].quantity;
                newPosition.isLong = schnorrData.positions[i].isLong;
                newPosition.entryPrice = schnorrData.positions[i].entryPrice;
                newPosition.createdTimestamp = schnorrData
                    .positions[i]
                    .createdTimestamp;

                uint256 colLen = schnorrData.positions[i].collaterals.length;
                for (uint256 j = 0; j < colLen; j++) {
                    newPosition.collaterals.push(
                        Crypto.Collateral({
                            oracleId: schnorrData
                                .positions[i]
                                .collaterals[j]
                                .oracleId,
                            token: schnorrData
                                .positions[i]
                                .collaterals[j]
                                .token,
                            quantity: schnorrData
                                .positions[i]
                                .collaterals[j]
                                .quantity,
                            entryPrice: schnorrData
                                .positions[i]
                                .collaterals[j]
                                .entryPrice
                        })
                    );
                }
            }

            emit DisputeChallenged(requestId, schnorrData.addr);
        } else {
            revert DisputeChallengeFailed();
        }
    }

    function getDisputeStatus(
        uint32 requestId
    )
        external
        view
        returns (bool isOpenDispute, uint64 timestamp, address user)
    {
        Dispute storage dispute = _disputes[requestId];
        isOpenDispute = dispute.status == uint8(DisputeStatus.Opened);
        timestamp = dispute.timestamp;
        user = dispute.user;
    }

    function getDisputePositions(
        uint32 requestId
    ) external view returns (Crypto.Position[] memory) {
        return _disputes[requestId].positions;
    }

    function getDisputeBalances(
        uint32 requestId
    ) external view returns (Crypto.Balance[] memory) {
        return _disputes[requestId].balances;
    }

    function updateLiquidatedPositions(
        uint32 requestId,
        uint256[] memory liquidatedIndexes,
        uint256 liquidatedCount,
        bool isCrossLiquidated
    ) external {
        require(msg.sender == dexSupporter, "Require Dex Supporter");

        Dispute storage dispute = _disputes[requestId];
        require(
            dispute.status == uint8(DisputeStatus.Opened),
            "Invalid dispute status"
        );

        // Update liquidated positions
        for (uint256 i = 0; i < liquidatedCount; i++) {
            uint256 index = liquidatedIndexes[i];
            dispute.positions[index].quantity = 0;
        }

        // If cross position is liquidated, update user balance
        if (isCrossLiquidated) {
            for (uint256 i = 0; i < dispute.balances.length; i++) {
                dispute.balances[i].balance = 0;
            }
        }
    }

    function updatePartialLiquidation(
        address user,
        address[] memory tokens,
        uint256[] memory losses,
        uint256 totalLossCount
    ) external nonReentrant {
        require(msg.sender == dexSupporter, "Unauthorized");
        require(tokens.length == losses.length, "Array length mismatch");
        require(totalLossCount <= tokens.length, "Invalid total loss count");

        for (uint256 i = 0; i < totalLossCount; i++) {
            address token = tokens[i];
            uint256 loss = losses[i];

            // Update deposited amount
            require(
                depositedAmount[user][token] >= loss,
                "Insufficient deposited amount"
            );
            depositedAmount[user][token] -= loss;

            // Transfer realized loss to insurance pool
            IERC20(token).transfer(lpProvider, loss);
            ILpProvider(lpProvider).increaseLpProvidedAmount(token, loss);

            emit PartialLiquidation(user, token, loss);
        }
    }

    function settleDisputeResult(
        uint32 requestId,
        uint256[] memory updatedBalances,
        uint256[] memory pnlValues,
        bool[] memory isProfits
    ) external nonReentrant {
        require(msg.sender == dexSupporter, "Unauthorized");

        Dispute storage dispute = _disputes[requestId];
        require(
            dispute.status == uint8(DisputeStatus.Opened),
            "Invalid dispute status"
        );

        for (uint256 i = 0; i < dispute.balances.length; i++) {
            address token = dispute.balances[i].addr;
            uint256 amount = updatedBalances[i];

            if (isProfits[i]) {
                ILpProvider(lpProvider).decreaseLpProvidedAmount(
                    token,
                    pnlValues[i]
                );
            } else {
                IERC20(token).transfer(lpProvider, pnlValues[i]);
                ILpProvider(lpProvider).increaseLpProvidedAmount(
                    token,
                    pnlValues[i]
                );
            }

            depositedAmount[dispute.user][token] = 0;
            IERC20(token).transfer(dispute.user, amount);
            emit Withdrawn(dispute.user, token, amount);

            dispute.balances[i].balance = amount;
        }

        dispute.status = uint8(DisputeStatus.Settled);
        emit DisputeSettled(requestId, dispute.user);
    }

    function setVaultParameters(
        uint256 _expiryTime,
        address _dexSupporter,
        address _lpProvider
    ) external onlyOwner {
        signatureExpiryTime = _expiryTime;
        dexSupporter = _dexSupporter;
        lpProvider = _lpProvider;
    }

    function setCombinedPublicKey(
        address _user,
        address _combinedPublicKey
    ) external onlyOwner {
        combinedPublicKey[_user] = _combinedPublicKey;
    }

    // function pause() external onlyOwner {
    //     require(block.timestamp - lastPausedTime > 1 days, "Pause too frequent"); 
    //     _pause();
    // }

    // function unpause() external onlyOwner {
    //     _unpause();
    //     lastPausedTime = block.timestamp;
    // }
}

